-- One bounded DUS programme snapshot; no personal NIF or inferred payments.
CREATE TABLE public.prtr_program_snapshot (
 program text PRIMARY KEY CHECK(program='DUS5000'),
 metadata jsonb NOT NULL CHECK((metadata->>'version'='idae-dus5000-v1' AND metadata->>'instrument'='MRR/PRTR' AND metadata->>'financing'='grant' AND jsonb_typeof(metadata->'rows')='array' AND jsonb_array_length(metadata->'rows') BETWEEN 1000 AND 5000 AND pg_column_size(metadata)<5000000) IS TRUE)
);
ALTER TABLE public.prtr_program_snapshot ENABLE ROW LEVEL SECURITY;
CREATE POLICY prtr_program_public_read ON public.prtr_program_snapshot FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.prtr_program_snapshot TO anon,authenticated;
GRANT ALL ON public.prtr_program_snapshot TO service_role;
